async def _drain_narration_queue(chat_id: int = -999) -> None:
    """
    Real fix (2026-08-22): mocking bot.narrate_action around an
    `await bot._do_attack(...)`-style call is NOT enough on its own --
    _post_narrated's real flavor line is only ever *enqueued*
    (_enqueue_narration, bot.py ~27864) for a SEPARATE background
    asyncio.Task (_chat_narration_worker) to actually pull and execute
    later; there's no guarantee that worker gets a turn on the event
    loop before the calling test's own `with patch(...)` block exits
    and un-mocks narrate_action, so the worker can end up calling the
    REAL function, hitting real Ollama, and hanging at
    asyncio.run()'s executor-shutdown wait (confirmed via a real
    faulthandler stack trace: a background thread stuck in
    ai/dm_agent.py's own requests.post call). _chat_narration_worker
    calls queue.task_done() after every item (bot.py ~27861), so
    queue.join() is a real, reliable way to wait for the worker to
    finish everything enqueued so far -- call this INSIDE the same
    `with patch("bot.narrate_action", ...)` block, right after the
    action, before the block exits.
    """
    queue = bot._CHAT_NARRATION_QUEUES.get(chat_id)
    if queue is not None:
        await queue.join()


class FastRegressionTests(unittest.IsolatedAsyncioTestCase):
    """
    No Ollama calls -- safe to run before every deploy. DB is
    initialized ONCE for the whole class (setUpClass, not setUp) since
    db.init_db() alone can take 60-90s+ under real disk contention on
    this machine (see project_ollama_single_slot_contention /
    documented CLAUDE.md latency notes) -- doing that per-test-method
    made a genuinely fast suite take many minutes for no real benefit,
    since the handful of tests that touch the DB use distinct
    user_ids and don't depend on a clean slate.
    """

    @classmethod
    def setUpClass(cls):
        use_test_db("tests/tmp/regression_fast.db")
        # Real live behavior change (2026-08-21, "active battle flow"):
        # _post_narrated now sleeps for a real, admin-tunable throttle
        # after every combat message it sends (default 2s in
        # production). This class's whole contract is "no Ollama calls
        # -- safe to run before every deploy," and a mandatory 2s sleep
        # per narrated action would silently violate that for every
        # combat test in this file -- forced to 0 here, class-wide, so
        # only a test that specifically wants to exercise the throttle
        # (which mocks _get_combat_throttle_seconds directly) ever sees
        # a non-zero value.
        db.set_setting("combat_throttle_seconds", "0")

    def setUp(self):
        # Real test-isolation fix (2026-08-21, "active battle flow"):
        # _CHAT_NARRATION_QUEUES/_CHAT_NARRATION_WORKERS are module-level
        # dicts, keyed by chat_id, holding a real asyncio.Queue + a real
        # asyncio.Task worker bound to whichever event loop created it.
        # unittest.IsolatedAsyncioTestCase gives every test method its
        # OWN fresh event loop -- a worker task created in one test's
        # loop is dead/unusable once that loop closes, but without this,
        # the NEXT test reusing the same chat_id (many tests share -999)
        # would find the OLD entry already present and try to enqueue
        # onto a queue whose worker belongs to a closed loop, producing
        # confusing cross-test failures that have nothing to do with
        # whatever that test is actually checking. Production never hits
        # this: the real bot process has exactly one persistent event
        # loop for its whole lifetime.
        bot._CHAT_NARRATION_QUEUES.clear()
        bot._CHAT_NARRATION_WORKERS.clear()

    # -- NPC-name stopword bug (v1.7.3) --------------------------------
    def test_npc_name_filler_words_dont_hijack_unrelated_messages(self):
        known_npcs = ["Grimsby", "Old Maren", "Sarah", "Theron", "Kess",
                      "Ossian Vane", "Borin Ironjaw", "Wren Hollowbrook",
                      "Pip Thistledown", "Grask Emberscale", "Vesh Nightglass"]
        # These all contain "the" or "old" and must NOT be swallowed by
        # per-word NPC matching just because a filler word overlaps.
        for text in ("Read the guest book on the landing table",
                     "Check out the door at the end of the hall",
                     "the old bridge creaks as I cross"):
            action = _keyword_fallback(text, known_npcs)["action"]
            self.assertNotEqual(action, "talk_npc", f"{text!r} was misrouted to talk_npc")

    def test_real_npc_names_still_resolve(self):
        known_npcs = ["Old Maren", "Theron", "Kess"]
        self.assertEqual(_keyword_fallback("Say hello to Maren", known_npcs)["action"], "talk_npc")
        self.assertEqual(_keyword_fallback("Say hello to Theron", known_npcs)["action"], "talk_npc")

