    async def test_attack_forced_roll_determines_hit_or_miss(self):
        import sessions
        sessions.end_session(-999)
        user_id = 900482
        make_basic_character(user_id, "Roller", current_location="crossroads_tavern")
        enemy_id = -2_500_053
        enemy = {
            "telegram_user_id": enemy_id, "name": "Dummy", "strength": 10, "dexterity": 10,
            "armor_class": 15, "hp_current": 100, "hp_max": 100, "is_ai": 1, "monster_key": "goblin",
        }
        player = db.get_character(user_id, -999)
        player["telegram_user_id"] = user_id
        session = sessions.start_session(-999, [player, enemy], {user_id: "party", enemy_id: "enemy"})
        session.turn_order = [user_id, enemy_id]
        session.current_turn_index = 0

        sink = []
        # A forced natural 1 should always miss (critical fail). The
        # dummy still needs a real "strength" score of its own in case
        # its own turn is resolved.
        #
        # narrate_action mocked (2026-08-21) -- real test-infrastructure
        # gap, not a hang in this test itself: the ATB rewrite
        # (v1.27.295) defers real flavor narration to a background
        # asyncio.to_thread job, and unittest.IsolatedAsyncioTestCase's
        # per-test event loop waits for that thread at teardown (real,
        # documented asyncio.run() executor-shutdown behavior -- never
        # happens in production, where the bot's own event loop runs
        # continuously). Confirmed via git stash this "hang" pre-dates
        # today's session but is real and reproducible either way.
        # bot._advance_turn_and_resolve_ai_turns also mocked (2026-08-22)
        # -- this test's own assertion only checks the enemy's hp stayed
        # unchanged by the player's own miss, never the outcome of the
        # dummy's own counter-turn, so skipping it changes nothing this
        # test actually verifies, while also removing a second real
        # background-narration race (the dummy's own counter-turn can
        # itself queue a real Ollama call that doesn't always finish
        # before the mock above goes out of scope -- confirmed real via
        # direct stress-testing, ~1/8 runs).
        from unittest.mock import patch, AsyncMock
        with patch("bot.narrate_action", return_value="The attack goes wide."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(FakeUpdate(user_id, "I attack the dummy", sink), "I attack the dummy", forced_roll=1)
            await _drain_narration_queue()
        self.assertEqual(enemy["hp_current"], 100, "a forced natural 1 should never hit")
        sessions.end_session(-999)

    async def test_attack_with_a_named_owned_weapon_auto_equips_it(self):
        """
        Real live bug, dev-topic screenshot (2026-08-08): "Attack spider
        4 with silvered dagger" -- "Was supposed to use the silvered
        dagger not shortsword." _weapon_for_attacker only ever reads
        the character's currently-equipped weapon; the "with <weapon>"
        clause was silently discarded, so a player naming a different
        carried weapon than what's equipped always still attacked with
        whatever was already equipped. A player who owns (but hasn't
        equipped) a silvered dagger, attacking "with silvered dagger",
        must end the attack with it actually equipped -- and the
        combat-result narration must name it, not the old shortsword.
        """
        import sessions
        sessions.end_session(-999)
        user_id = 900483
        make_basic_character(user_id, "DaggerWielder", current_location="crossroads_tavern",
                              inventory={"shortsword": 1, "silvered_dagger": 1})
        db.equip_item(user_id, -999, "shortsword")
        enemy_id = -2_500_054
        enemy = {
            "telegram_user_id": enemy_id, "name": "Spider 4", "strength": 10, "dexterity": 10,
            "armor_class": 5, "hp_current": 50, "hp_max": 50, "is_ai": 1, "monster_key": "goblin",
        }
        player = db.get_character(user_id, -999)
        self.assertEqual(player.get("equipped_weapon"), "shortsword")
        player["telegram_user_id"] = user_id
        session = sessions.start_session(-999, [player, enemy], {user_id: "party", enemy_id: "enemy"})
        session.turn_order = [user_id, enemy_id]
        session.current_turn_index = 0

        # bot.narrate_action mocked -- otherwise this forced hit queues a
        # real background Ollama narration call that asyncio.run()'s
        # executor shutdown waits on at teardown (same root cause as
        # test_attack_forced_roll_determines_hit_or_miss above).
        # bot._advance_turn_and_resolve_ai_turns also mocked -- neither
        # assertion below depends on the enemy's own counter-turn, and
        # skipping it removes a second real background-narration race
        # (see the same note on test_attack_forced_roll_determines_hit_
        # or_miss above).
        from unittest.mock import patch, AsyncMock
        sink = []
        with patch("bot.narrate_action", return_value="A blow lands."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(
                FakeUpdate(user_id, "Attack spider 4 with silvered dagger", sink),
                "Attack spider 4 with silvered dagger", forced_roll=20,
            )
            await _drain_narration_queue()
        live = next(p for p in session.participants if p["telegram_user_id"] == user_id)
        self.assertEqual(live.get("equipped_weapon"), "silvered_dagger")
        self.assertEqual(db.get_character(user_id, -999).get("equipped_weapon"), "silvered_dagger")
        self.assertTrue(any("silvered dagger" in line.lower() for line in sink))

        # No regression: attacking with no weapon named, or already
        # holding the named one, changes nothing and equips nothing new.
        sessions.end_session(-999)
        user_id2 = 900484
        make_basic_character(user_id2, "PlainAttacker", current_location="crossroads_tavern")
        enemy2 = {
            "telegram_user_id": -2_500_055, "name": "Dummy2", "strength": 10, "dexterity": 10,
            "armor_class": 20, "hp_current": 50, "hp_max": 50, "is_ai": 1, "monster_key": "goblin",
        }
        player2 = db.get_character(user_id2, -999)
        equipped_before = player2.get("equipped_weapon")
        player2["telegram_user_id"] = user_id2
        session2 = sessions.start_session(-999, [player2, enemy2], {user_id2: "party", -2_500_055: "enemy"})
        session2.turn_order = [user_id2, -2_500_055]
        with patch("bot.narrate_action", return_value="The attack goes wide."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(FakeUpdate(user_id2, "I attack the dummy", []), "I attack the dummy", forced_roll=1)
            await _drain_narration_queue()
        self.assertEqual(db.get_character(user_id2, -999).get("equipped_weapon"), equipped_before)
        sessions.end_session(-999)

    async def test_equip_command_mid_combat_updates_the_live_session_not_just_the_db(self):
        """
        Real live bug (2026-08-20, dev-bridge, Charvenna, two separate
        reports): "I equipped the shortsword so why did it use the
        tempered dagger" / "My silvered dagger is equipped so why is it
        using the tempered dagger." Different shape than the sibling
        test above (which covers naming a weapon INLINE inside the
        attack text itself, e.g. "attack X with Y") -- this is the
        SEPARATE real "equip X" command, said on its own mid-fight, not
        as part of an attack. _do_equip_item only ever wrote the new
        equipped_weapon to the database (db.equip_item) -- the live
        combat session's own participant dict (a separate in-memory
        copy _weapon_for_attacker reads directly) never got told, so a
        mid-fight equip was silently ignored by every subsequent plain
        "attack" until the fight ended. ("Tempered Dagger" itself is a
        real, procedurally-generated per-instance magic item --
        rules/item_generator.py -- not a hallucination; the bug is that
        combat kept using WHATEVER weapon was equipped at the live
        session's own start, ignoring a real mid-fight re-equip.) Fixed
        via _sync_live_combat_equipment, called right after a
        successful db.equip_item.
        """
        import sessions
        sessions.end_session(-999)
        user_id = 900485
        make_basic_character(user_id, "MidFightEquipper", current_location="crossroads_tavern",
                              inventory={"shortsword": 1, "silvered_dagger": 1})
        db.equip_item(user_id, -999, "shortsword")
        enemy_id = -2_500_056
        enemy = {
            "telegram_user_id": enemy_id, "name": "Spider 5", "strength": 10, "dexterity": 10,
            "armor_class": 5, "hp_current": 50, "hp_max": 50, "is_ai": 1, "monster_key": "goblin",
        }
        player = db.get_character(user_id, -999)
        self.assertEqual(player.get("equipped_weapon"), "shortsword")
        player["telegram_user_id"] = user_id
        session = sessions.start_session(-999, [player, enemy], {user_id: "party", enemy_id: "enemy"})
        session.turn_order = [user_id, enemy_id]
        session.current_turn_index = 0

        sink = []
        await bot._do_equip_item(FakeUpdate(user_id, "equip silvered dagger", sink), "equip silvered dagger")
        live = next(p for p in session.participants if p["telegram_user_id"] == user_id)
        self.assertEqual(live.get("equipped_weapon"), "silvered_dagger")

        # bot.narrate_action and bot._advance_turn_and_resolve_ai_turns
        # mocked -- see the note on
        # test_attack_with_a_named_owned_weapon_auto_equips_it above.
        from unittest.mock import patch, AsyncMock
        sink2 = []
        with patch("bot.narrate_action", return_value="A blow lands."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(FakeUpdate(user_id, "attack spider 5", sink2), "attack spider 5", forced_roll=20)
            await _drain_narration_queue()
        self.assertTrue(any("silvered dagger" in line.lower() for line in sink2), sink2)
        self.assertFalse(any("shortsword" in line.lower() for line in sink2), sink2)
        sessions.end_session(-999)

