        sink = []
        update = FakeUpdate(700002, "/set_topic adventure", sink, thread_id=555, chat_id=-5559999)
        context = DummyContext(bot=FakeBot(status="member"), args=["adventure"])
        await bot.set_topic_command(update, context)
