    async def test_turn_prompt_not_repeated_on_a_resolve_ai_turns_reentry(self):
        # Real live bug (2026-08-05, Coffee, Development topic screenshot:
        # "What os happening?! I have two attacks now?!"): the "Round N
        # -- it's now X's turn!" prompt posted twice back to back with
        # nothing in between. Same root cause as the multiattack-
        # announcement bug above: whatever handler originally triggered
        # an AI-turn-resolution chain can get retried after a downstream
        # failure, and since the human's turn never actually advanced,
        # the retry re-enters _resolve_ai_turns and, with no AI turns
        # left to resolve, goes straight back to "not is_ai" and used to
        # re-announce the same prompt.
        import sessions
        sessions.end_session(-999)
        human_id = 900921
        make_basic_character(human_id, "Ravenloft2", current_location="crossroads_tavern")
        human = db.get_character(human_id, -999)
        goblin = {
            "telegram_user_id": -700602, "name": "Goblin 2", "is_ai": True,
            "hp_current": 25, "hp_max": 25, "armor_class": 10,
            "strength": 8, "dexterity": 14, "proficiency_bonus": 2,
            "monster_key": "goblin", "xp_reward": 10, "conditions": [],
        }
        session = sessions.start_session(-999, [human, goblin], {human_id: "party", -700602: "enemy"})
        session.turn_order = [human_id, -700602]
        session.current_turn_index = 0

        sink = []
        update = FakeUpdate(human_id, "irrelevant", sink)

        await bot._resolve_ai_turns(update, session)
        self.assertEqual(sum(1 for line in sink if "What do you do" in line), 1)

        # Simulated re-entry: the same still-current, un-advanced human
        # turn gets resolved again.
        await bot._resolve_ai_turns(update, session)
        self.assertEqual(
            sum(1 for line in sink if "What do you do" in line), 1,
            f"turn prompt should appear exactly once total across the re-entry, got: {sink}",
        )
        self.assertEqual(session.current_participant_id(), human_id)

    async def test_restart_snapshot_restore_clears_stale_turn_prompt_flag(self):
        """
        Real live bug (2026-08-19, traced from Sugar's dev-bridge report
        "why is my character attacking in battle when I haven't had a
        chance to select what to do"): sessions.Session.to_json_dict
        round-trips participant dicts VERBATIM, including the in-memory
        -only _turn_prompt_announced flag (see the test just above --
        meant to survive only a same-request retry, cleared by
        advance_turn() once a turn genuinely ends). A snapshot saved
        right after that flag was set (e.g. a restart landing seconds
        after the "it's your turn" prompt went out) restores it still
        True, so bot.py's _on_startup restore path correctly determined
        it was still a real player's turn but silently skipped
        re-sending the battle menu, thinking it already had -- the
        player was left with only a bare restart notice and no working
        buttons. _on_startup now pops the same 3 announce flags
        advance_turn() itself already pops, for whoever's turn it
        currently is, right before calling _resolve_ai_turns -- this
        confirms that clearing (simulating the restore) is what makes
        the fresh re-announce actually happen.
        """
        import sessions
        sessions.end_session(-999)
        human_id = 900922
        make_basic_character(human_id, "RestoredPlayer", current_location="crossroads_tavern")
        human = db.get_character(human_id, -999)
        goblin = {
            "telegram_user_id": -700603, "name": "Goblin 3", "is_ai": True,
            "hp_current": 25, "hp_max": 25, "armor_class": 10,
            "strength": 8, "dexterity": 14, "proficiency_bonus": 2,
            "monster_key": "goblin", "xp_reward": 10, "conditions": [],
        }
        session = sessions.start_session(-999, [human, goblin], {human_id: "party", -700603: "enemy"})
        session.turn_order = [human_id, -700603]
        session.current_turn_index = 0

        # Simulates the real bug: a snapshot restored with the flag
        # already True (round-tripped verbatim from before the restart),
        # same as a real Session.from_json_dict would produce.
        current = session.current_participant()
        current["_turn_prompt_announced"] = True

        sink = []
        update = FakeUpdate(human_id, "irrelevant", sink)
        await bot._resolve_ai_turns(update, session)
        self.assertEqual(
            sum(1 for line in sink if "What do you do" in line), 0,
            "confirms the bug reproduces: a stale True flag suppresses the real re-announce",
        )

        # The actual fix: _on_startup's restore path pops this flag
        # (among the other 2 announce flags) for the current participant
        # right before calling _resolve_ai_turns.
        current.pop("_turn_prompt_announced", None)
        await bot._resolve_ai_turns(update, session)
        self.assertEqual(
            sum(1 for line in sink if "What do you do" in line), 1,
            "a genuinely fresh battle menu with working buttons must go out after the flag is cleared",
        )
        sessions.end_session(-999)
        sessions.end_session(-999)

    async def test_human_attack_multiattack_announcement_not_repeated_on_a_crash_and_retry(self):
        # Real gap found in a follow-up audit (2026-08-05) after fixing
        # the AI-turn version of this bug: _do_attack's OWN "X has N
        # attacks this turn!" line (Extra Attack/Action Surge/Flurry of
        # Blows, for a REAL human player) had no guard at all, unlike
        # its twin in _resolve_ai_turns fixed earlier the same day.
        # Same crash-then-retry root cause (a downstream failure, e.g.
        # this box's known disk-I/O contention, leaves the turn stuck
        # un-advanced; the next retry re-announces it).
        from unittest.mock import patch
        import sessions
        sessions.end_session(-999)
        uid = 900951
        make_basic_character(uid, "Fighter5b", char_class="Fighter", current_location="crossroads_tavern")
        db.update_character(uid, -999, level=5)  # real Extra Attack (2 attacks/turn)
        character = db.get_character(uid, -999)
        character["telegram_user_id"] = uid
        goblin = {
            "telegram_user_id": -700702, "name": "Goblin Y", "is_ai": True,
            "hp_current": 200, "hp_max": 200, "armor_class": 1,
            "strength": 8, "dexterity": 14, "proficiency_bonus": 2,
            "monster_key": "goblin", "xp_reward": 10, "conditions": [],
        }
        session = sessions.start_session(-999, [character, goblin], {uid: "party", -700702: "enemy"})
        session.turn_order = [uid, -700702]
        session.current_turn_index = 0

        sink = []
        update = FakeUpdate(uid, "I attack", sink)

        call_count = {"n": 0}
        real_sync = bot._sync_player_to_db

        def flaky_sync(char):
            call_count["n"] += 1
            if call_count["n"] == 1:
                raise RuntimeError("simulated transient DB failure")
            return real_sync(char)

        # bot.narrate_action mocked -- these two real (unforced-roll)
        # attacks would otherwise each queue a real background Ollama
        # narration call that asyncio.run()'s executor shutdown waits
        # on at teardown (same root cause as
        # test_attack_forced_roll_determines_hit_or_miss elsewhere).
        # bot._advance_turn_and_resolve_ai_turns also mocked -- the
        # assertion only ever counts "has 2 attacks" lines (the
        # player's own multiattack announcement), never anything from
        # the goblin's own counter-turn, so skipping it removes a
        # second real background-narration race for free (see the same
        # note on test_attack_forced_roll_determines_hit_or_miss).
        from unittest.mock import AsyncMock
        with patch("bot._sync_player_to_db", side_effect=flaky_sync), \
             patch("bot.narrate_action", return_value="A blow lands."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            with self.assertRaises(RuntimeError):
                await bot._do_attack(update, "I attack")
            await _drain_narration_queue()

        self.assertEqual(sum(1 for line in sink if "has 2 attacks" in line), 1)

        with patch("bot.narrate_action", return_value="A blow lands."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(update, "I attack")
            await _drain_narration_queue()
        self.assertEqual(
            sum(1 for line in sink if "has 2 attacks" in line), 1,
            f"multiattack announcement should appear exactly once total across the crash+retry, got: {sink}",
        )
        sessions.end_session(-999)

