    def test_narration_cache_lookup_and_remember_round_trip(self):
        import tempfile
        from ai import narration_cache
        from unittest.mock import patch
        with tempfile.TemporaryDirectory() as tmp:
            with patch("ai.narration_cache.CACHE_DIR", tmp), \
                 patch("ai.narration_cache.CACHE_DB_PATH", f"{tmp}/n.db"):
                key = "Fighter:hit:low"
                # Below MIN_VARIANTS_BEFORE_REUSE: never reused yet, even with a guaranteed-hit roll.
                narration_cache.remember(key, "Variant one.")
                narration_cache.remember(key, "Variant two.")
                with patch("ai.narration_cache.random.random", return_value=0.0):
                    self.assertIsNone(narration_cache.lookup(key))
                # Warmed up to MIN_VARIANTS_BEFORE_REUSE: a guaranteed-hit roll now reuses a real stored variant.
                narration_cache.remember(key, "Variant three.")
                with patch("ai.narration_cache.random.random", return_value=0.0):
                    reused = narration_cache.lookup(key)
                self.assertIn(reused, ("Variant one.", "Variant two.", "Variant three."))
                # A guaranteed-miss roll still falls through to None even once warm.
                with patch("ai.narration_cache.random.random", return_value=1.0):
                    self.assertIsNone(narration_cache.lookup(key))
                # Caps at MAX_VARIANTS_PER_KEY -- doesn't grow past it.
                for i in range(20):
                    narration_cache.remember(key, f"Extra {i}.")
                with narration_cache._connect() as conn:
                    count = conn.execute("SELECT COUNT(*) FROM variants WHERE key = ?", (key,)).fetchone()[0]
                self.assertEqual(count, narration_cache.MAX_VARIANTS_PER_KEY)

    def test_narration_cache_reuse_never_carries_a_stale_attacker_or_defender_name(self):
        """
        Real live bug (2026-08-15 dev-topic reports): a routine narration
        line generated for one fight (Ravenloft vs. Goblin Shaman) was later
        replayed verbatim for a totally different fight (a different Warlock
        vs. Crystal Spider) because cache_key() buckets only by class/outcome/
        damage tier, never by who's actually fighting. Confirms remember()
        strips the ORIGINAL real names into placeholders, and lookup() refills
        them with THIS turn's real names -- never the stale ones.
        """
        import tempfile
        from ai import narration_cache
        from unittest.mock import patch
        with tempfile.TemporaryDirectory() as tmp:
            with patch("ai.narration_cache.CACHE_DIR", tmp), \
                 patch("ai.narration_cache.CACHE_DB_PATH", f"{tmp}/n.db"):
                key = "Warlock:hit:mid"
                for text in (
                    "Ravenloft's blade finds Goblin Shaman for a solid hit!",
                    "Ravenloft lands a heavy blow on Goblin Shaman!",
                    "Ravenloft cuts through Goblin Shaman's guard!",
                ):
                    narration_cache.remember(key, text, actor_name="Ravenloft", defender_name="Goblin Shaman")
                with narration_cache._connect() as conn:
                    stored = [r[0] for r in conn.execute("SELECT text FROM variants WHERE key = ?", (key,)).fetchall()]
                # Stored text must never contain the original real names --
                # only the placeholders, so a later reuse can't go stale.
                for text in stored:
                    self.assertNotIn("Ravenloft", text)
                    self.assertNotIn("Goblin Shaman", text)
                    self.assertIn("{ACTOR}", text)
                    self.assertIn("{DEFENDER}", text)
                with patch("ai.narration_cache.random.random", return_value=0.0):
                    reused = narration_cache.lookup(key, actor_name="Dusk", defender_name="Crystal Spider 3")
                self.assertIn("Dusk", reused)
                self.assertIn("Crystal Spider 3", reused)
                self.assertNotIn("Ravenloft", reused)
                self.assertNotIn("Goblin Shaman", reused)

    def test_purge_stale_unplaceholdered_rows_removes_pre_fix_baked_names(self):
        """
        Real dev-bridge report (2026-08-18, Coffee): "Why is it still
        saying goblin shaman you said you fixed this issue?" -- reported
        3 SEPARATE times (2026-08-14/15/16) after v1.27.235's own
        "fix narration cache stale-identity bug" had already shipped.
        Root cause, confirmed by reading the real live cache file: that
        fix only changed what NEW writes look like -- 182 of 273 rows
        already sitting in n.db from before the fix still hard-baked
        real fighters' names with no {ACTOR}/{DEFENDER} token at all,
        including the EXACT line from Coffee's report. MAX_VARIANTS_PER_
        KEY's cap meant remember() had been silently refusing to add any
        correctly placeholder-ized replacement to an already-full
        bucket ever since -- these rows were permanent, not slow to age
        out. This migration purges exactly the un-placeholder-ized
        rows, once, and never rescans on a later call.
        """
        import tempfile
        from ai import narration_cache
        from unittest.mock import patch
        with tempfile.TemporaryDirectory() as tmp:
            with patch("ai.narration_cache.CACHE_DIR", tmp), \
                 patch("ai.narration_cache.CACHE_DB_PATH", f"{tmp}/n.db"):
                key = "Warlock:miss:0"
                with narration_cache._connect() as conn:
                    # Simulate real pre-fix poisoned rows (bypassing remember(),
                    # which already placeholder-izes on this branch).
                    conn.execute(
                        "INSERT INTO variants (key, text) VALUES (?, ?)",
                        (key, "Ravenloft swings and misses (rolled a 9) against Goblin Shaman 2!"),
                    )
                    conn.execute(
                        "INSERT INTO variants (key, text) VALUES (?, ?)",
                        (key, "Some purely atmospheric line with no real name in it at all."),
                    )
                # A real, correctly placeholder-ized post-fix row, which must survive.
                narration_cache.remember(key, "{ACTOR} swings and misses against {DEFENDER}!", actor_name="X", defender_name="Y")

                deleted = narration_cache.purge_stale_unplaceholdered_rows()
                self.assertEqual(deleted, 2)
                with narration_cache._connect() as conn:
                    remaining = [r[0] for r in conn.execute("SELECT text FROM variants WHERE key = ?", (key,)).fetchall()]
                self.assertEqual(remaining, ["{ACTOR} swings and misses against {DEFENDER}!"])

                # Safe to rerun -- a second call is a real no-op, not a re-scan.
                self.assertEqual(narration_cache.purge_stale_unplaceholdered_rows(), 0)

