    async def test_guild_curriculum_riddle_ignores_ordinary_chat_but_credits_a_real_answer(self):
        """
        Real live bug (2026-08-12, caught by topic-activity monitoring):
        a guild topic also carries ordinary member chat, unlike
        campaign.json's own puzzle system (which only ever runs against
        text already classified as an "answer_puzzle" attempt) -- a
        plain substring check against every message sent while a
        solve_puzzle step is current meant an unrelated question just
        mentioning the answer word instantly finished the riddle and
        skipped the member to the next lesson. Fixed via
        bot._guild_curriculum_riddle_answer_matches (exact match after
        stripping a short natural lead-in, see its own docstring for why
        a word-count cap alone wasn't enough) -- this test locks in both
        halves: ordinary chat must NOT complete it, and a real short
        answer still must.

        Real regression found 2026-08-21 (same stale-answer class as
        test_secondary_guild_solve_puzzle_step_credits_correctly): this
        test originally used "a map" -- the answer to this step's OLD
        riddle before 2026-08-14's real, deliberate swap (a leaked
        answer forced a new riddle; see guild_curriculum.py's own
        comment on "arc_2_the_first_riddle"). Updated to the real
        current riddle's own accepted answer ("an echo"/"echo").
        """
        from unittest.mock import patch
        user_id = 700104
        make_basic_character(
            user_id, "CurriculumTester4", char_class="Wizard", current_location="market_row",
            ability_scores={"strength": 8, "dexterity": 12, "constitution": 14,
                             "intelligence": 17, "wisdom": 10, "charisma": 10},
        )
        db.update_character(user_id, -999, level=10, proven_in_combat=True, subclass="Evocation")
        with patch("bot.narrate_skill_check", return_value="ok"):
            await bot._do_join_guild(FakeUpdate(user_id, "I join the Arcane Circle", []), "I join the Arcane Circle")
        db.update_character(user_id, -999, guild_curriculum_step=1, guild_curriculum_step_unlocked_at="2020-01-01T00:00:00+00:00")

        sink = []
        update = FakeUpdate(
            user_id, "Does anyone know if there's an echo in these old tunnels?", sink,
            thread_id=config.GUILD_TOPIC_IDS["arcane_circle"],
        )
        await bot.guild_topic_handler(update, DummyContext(), "arcane_circle")
        char = db.get_character(user_id, -999)
        self.assertEqual(char["guild_curriculum_step"], 1, "ordinary chat mentioning the answer word must not complete the riddle")

        sink = []
        update = FakeUpdate(user_id, "I think it's an echo", sink, thread_id=config.GUILD_TOPIC_IDS["arcane_circle"])
        await bot.guild_topic_handler(update, DummyContext(), "arcane_circle")
        char = db.get_character(user_id, -999)
        self.assertEqual(char["guild_curriculum_step"], 2, "a real short answer attempt must still be credited")

    async def test_guild_curriculum_riddle_word_count_alone_was_not_enough(self):
        """
        Real live bug, second half (2026-08-12, same-day hardening pass):
        the FIRST fix above (a 6-word cap on top of a substring check)
        genuinely closed the reported repro, but a short, generic answer
        word like "steps" (one of the Thieves' Guild riddle's accepted
        answers) can still appear, as a whole word, inside an unrelated
        sentence that's ALSO 6 words or fewer -- "What are the next
        steps here?" is exactly 6 words and contains "steps". Confirmed
        this would have still slipped through the word-count-only fix;
        the real fix (exact match after stripping a short lead-in) closes
        it for good since an unrelated sentence essentially never happens
        to equal the bare answer exactly.
        """
        from unittest.mock import patch
        user_id = 700105
        make_basic_character(
            user_id, "CurriculumTester5", char_class="Rogue", current_location="crossroads_tavern",
        )
        db.update_character(user_id, -999, level=10, proven_in_combat=True, subclass="Thief")
        await bot._do_join_guild(FakeUpdate(user_id, "I join the Thieves' Guild", []), "I join the Thieves' Guild")
        char = db.get_character(user_id, -999)
        self.assertEqual(char["guild"], "thieves_guild")
        db.update_character(user_id, -999, guild_curriculum_step=3, guild_curriculum_step_unlocked_at="2020-01-01T00:00:00+00:00")

        sink = []
        update = FakeUpdate(
            user_id, "What are the next steps here?", sink, thread_id=config.GUILD_TOPIC_IDS["thieves_guild"],
        )
        await bot.guild_topic_handler(update, DummyContext(), "thieves_guild")
        char = db.get_character(user_id, -999)
        self.assertEqual(
            char["guild_curriculum_step"], 3,
            "a 6-word ordinary question containing the bare answer word must not complete the riddle",
        )

        sink = []
        update = FakeUpdate(user_id, "footsteps", sink, thread_id=config.GUILD_TOPIC_IDS["thieves_guild"])
        await bot.guild_topic_handler(update, DummyContext(), "thieves_guild")
        char = db.get_character(user_id, -999)
        self.assertEqual(char["guild_curriculum_step"], 4, "a real bare answer must still be credited")

    async def test_guild_curriculum_mastery_reward_lands_on_the_real_profession_key(self):
        """
        Real bug caught proactively (code review, not a live report): the
        Arcane Circle/Enchanters' Guild curriculum steps that grant a
        profession-mastery bump used "enchanting" as the profession key
        -- but this game has no "enchanting" profession at all. Every
        real ENCHANT_RECIPES entry (rules/crafting.py) declares
        "profession": "alchemy", the same key bot._roll_masterwork_
        quality/_profession_mastery_pct read for a real enchant's
        masterwork-quality odds. Rewarding an "enchanting" key was
        therefore silent and completely inert -- it created an orphaned
        dict entry nothing ever reads, never actually improving a
        member's real enchanting odds despite the reward text saying so.
        Fixed by rewarding "alchemy" instead, the real key.
        """
        import guild_curriculum as gc
        user_id = 700106
        make_basic_character(
            user_id, "CurriculumTester6", char_class="Wizard", current_location="market_row",
        )
        db.update_character(user_id, -999, guild="arcane_circle")
        step = gc.get_step("arcane_circle", 3)
        self.assertEqual(step["reward_mastery_profession"], "alchemy")

        char_before = db.get_character(user_id, -999)
        before_alchemy = char_before["profession_mastery_pct"].get("alchemy", bot.PROFICIENCY_STARTING_PCT)

        sink = []
        await bot._complete_guild_curriculum_step(FakeUpdate(user_id, "", sink), user_id, -999, step)

        char_after = db.get_character(user_id, -999)
        after_pct = char_after["profession_mastery_pct"]
        self.assertNotIn("enchanting", after_pct, "must never write an orphaned 'enchanting' key")
        self.assertEqual(after_pct.get("alchemy"), before_alchemy + step["reward_mastery_pct"])
        # Same key a real enchant's masterwork roll actually reads.
        self.assertEqual(bot._profession_mastery_pct(char_after, "alchemy"), after_pct["alchemy"])

    def test_guild_curriculum_alignment_choice_announcement_has_a_call_to_action(self):
        """
        Real bug caught proactively (direct reproduction, not a live
        report): bot._format_guild_curriculum_step_announcement used to
        skip the whole 🎯 objective line for an alignment_choice step, on
        the reasoning that its real setup/choices shouldn't be spoiled in
        the auto-posted announcement -- but that also skipped the plain,
        SAFE hint every other step type gets ("say 'my curriculum' to see
        it"), and bot._format_guild_curriculum_step_objective never even
        had an alignment_choice branch to begin with (fell through to a
        bare ""). Confirmed via direct reproduction: the real posted+
        pinned text for every alignment_choice step (one per guild, 7
        total) was just the title and flavor, with literally no
        indication anywhere that anything was expected of the member
        next. Fixed by giving _format_guild_curriculum_step_objective a
        real alignment_choice branch and always including it.
        """
        import guild_curriculum as gc
        for guild_id in gc.GUILD_CURRICULUM:
            for step in gc.get_curriculum(guild_id):
                if step["trigger"]["type"] != "alignment_choice":
                    continue
                text = bot._format_guild_curriculum_step_announcement(step)
                self.assertIn("my curriculum", text.lower(), f"{guild_id}/{step['id']} announcement has no call to action")
                self.assertNotIn("XP", text, f"{guild_id}/{step['id']} announcement must not spoil the reward")
                self.assertNotIn("gold", text, f"{guild_id}/{step['id']} announcement must not spoil the reward")

    def test_guild_curriculum_location_monster_material_objectives_say_where_to_act(self):
        """
        Real live report (2026-08-12, dev-bridge screenshot + "How do we
        complete the quests?"): reach_location/defeat_monster/
        gather_material objectives told a member WHAT to do ("Travel to
        Market Row.") but never WHERE, unlike solve_puzzle/npc_dialogue/
        dice_challenge/alignment_choice, which all explicitly say "in the
        Adventure topic" or "right here" -- these steps post in the
        GUILD topic but must be acted on in Adventure, same as any other
        move/gather/combat action, and a member reading only the guild
        topic had no way to know that. Confirmed via this exact player's
        own guild topic screenshot (Adventurers' Guild step 0: "Travel to
        Market Row."). Fixed by appending ", in the Adventure topic." to
        all three of these objective branches.
        """
        import guild_curriculum as gc
        for guild_id in gc.GUILD_CURRICULUM:
            for step in gc.get_curriculum(guild_id):
                if step["trigger"]["type"] not in ("reach_location", "defeat_monster", "gather_material"):
                    continue
                objective = bot._format_guild_curriculum_step_objective(step)
                self.assertIn(
                    "Adventure topic", objective,
                    f"{guild_id}/{step['id']} objective doesn't say where to act: {objective!r}",
                )

